const fliptAcceptServerVersionHeader = "x-flipt-accept-server-version"

var defaultFliptAcceptServerVersion = semver.Version{Major: 1}

type fliptAcceptServerVersionContextKey struct{}

// WithFliptAcceptServerVersion returns a context containing the client's accepted server version.
func WithFliptAcceptServerVersion(ctx context.Context, version semver.Version) context.Context {
	return context.WithValue(ctx, fliptAcceptServerVersionContextKey{}, version)
}

// FliptAcceptServerVersionFromContext returns the client's accepted server version.
// It returns the default version when the context has no version.
func FliptAcceptServerVersionFromContext(ctx context.Context) semver.Version {
	if version, ok := ctx.Value(fliptAcceptServerVersionContextKey{}).(semver.Version); ok {
		return version
	}

	return defaultFliptAcceptServerVersion
}

// FliptAcceptServerVersionUnaryInterceptor stores the client's accepted server version in the request context.
func FliptAcceptServerVersionUnaryInterceptor(logger *zap.Logger) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
		version := defaultFliptAcceptServerVersion
		if md, ok := metadata.FromIncomingContext(ctx); ok {
			if values := md.Get(fliptAcceptServerVersionHeader); len(values) > 0 {
				parsed, err := semver.ParseTolerant(values[0])
				if err != nil {
					logger.Debug("invalid client accepted server version", zap.String("version", values[0]), zap.Error(err))
				} else {
					version = parsed
				}
			}
		}

		return handler(WithFliptAcceptServerVersion(ctx, version), req)
	}
}

// ValidationUnaryInterceptor validates incoming requests
func ValidationUnaryInterceptor(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
	if v, ok := req.(flipt.Validator); ok {
		if err := v.Validate(); err != nil {
			return nil, err
		}
	}

	return handler(ctx, req)
}

// ErrorUnaryInterceptor intercepts known errors and returns the appropriate GRPC status code
func ErrorUnaryInterceptor(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
	resp, err = handler(ctx, req)
	if err == nil {
		return resp, nil
	}

	metrics.ErrorsTotal.Add(ctx, 1)

	// given already a *status.Error then forward unchanged
	if _, ok := status.FromError(err); ok {
		return
	}

	if errors.Is(err, context.Canceled) {
		err = status.Error(codes.Canceled, err.Error())
		return
	}

	if errors.Is(err, context.DeadlineExceeded) {
		err = status.Error(codes.DeadlineExceeded, err.Error())
		return
	}

	code := codes.Internal
	switch {
	case errs.AsMatch[errs.ErrNotFound](err):
		code = codes.NotFound
	case errs.AsMatch[errs.ErrInvalid](err),
		errs.AsMatch[errs.ErrValidation](err):
		code = codes.InvalidArgument
	case errs.AsMatch[errs.ErrUnauthenticated](err):
		code = codes.Unauthenticated
	}

	err = status.Error(code, err.Error())
	return
}

